1	package org.jsoup.nodes;
2	
3	import org.jsoup.Connection;
4	import org.jsoup.Jsoup;
5	import org.jsoup.helper.HttpConnection;
6	import org.jsoup.helper.Validate;
7	import org.jsoup.internal.StringUtil;
8	import org.jsoup.parser.Tag;
9	import org.jsoup.select.Elements;
10	import org.jsoup.select.Evaluator;
11	import org.jsoup.select.Selector;
12	import org.jspecify.annotations.Nullable;
13	
14	import java.util.ArrayList;
15	import java.util.List;
16	
17	/**
18	 * An HTML Form Element provides ready access to the form fields/controls that are associated with it. It also allows a
19	 * form to easily be submitted.
20	 */
21	public class FormElement extends Element {
22	    // Listed controls whose form= attribute names their owning form, per the HTML spec
23	    private static final String[] FormOwnerTags =
24	        {"input", "keygen", "object", "select", "textarea"};
25	    private static final Evaluator formOwnerControl =
26	        Selector.evaluatorOf(StringUtil.join(FormOwnerTags, ", "));
27	    // All parser-listed form controls (the five above plus button, fieldset, output), considered for association
28	    private static final String[] ListedControlTags =
29	        {"button", "fieldset", "input", "keygen", "object", "output", "select", "textarea"};
30	    private static final Evaluator listedControl =
31	        Selector.evaluatorOf(StringUtil.join(ListedControlTags, ", "));
32	
33	    // controls linked to this form by the parser; due to parse recovery, they may not be descendants of this form
34	    private final Elements linkedEls = new Elements();
35	
36	    /**
37	     * Create a new, standalone form element.
38	     *
39	     * @param tag        tag of this element
40	     * @param baseUri    the base URI
41	     * @param attributes initial attributes
42	     */
43	    public FormElement(Tag tag, @Nullable String baseUri, @Nullable Attributes attributes) {
44	        super(tag, baseUri, attributes);
45	    }
46	
47	    /**
48	     * Get the list of form control elements associated with this form.
49	     * <p>Association follows the HTML form ownership rules and is recomputed on every call, so moving nodes, or
50	     * changing a control's {@code form} attribute or a form's {@code id}, is reflected immediately:</p>
51	     * <ul>
52	     * <li>a listed control ({@code input}, {@code keygen}, {@code object}, {@code select}, {@code textarea}) that has a
53	     * {@code form} attribute is owned by the element in the same document whose {@code id} equals that value, but only
54	     * when that element is itself a {@code FormElement}; this lets the control sit outside this form, or even inside
55	     * another form, as the explicit owner takes precedence over an ancestor form;</li>
56	     * <li>a control without a {@code form} attribute is owned by its nearest ancestor {@code FormElement};</li>
57	     * <li>a control with no ancestor form that was linked to this form by the parser (for example, an input hoisted out
58	     * of a form during table recovery) stays associated with it;</li>
59	     * <li>a {@code form} attribute that is empty, names a missing element, or names an element that is not a form,
60	     * leaves the control unassociated — there is no fall back to an ancestor form.</li>
61	     * </ul>
62	     * The returned controls are in document order and de-duplicated.
63	     * @return form controls associated with this element
64	     */
65	    public Elements elements() {
66	        Elements associated = new Elements();
67	        Document owner = ownerDocument();
68	        if (owner == null) {
69	            // a detached form: consider its own descendants and any controls linked directly to it
70	            Elements candidates = select(listedControl);
71	            for (Element linkedEl : linkedEls) {
72	                if (linkedEl.ownerDocument() == null && !candidates.contains(linkedEl))
73	                    candidates.add(linkedEl);
74	            }
75	            for (Element el : candidates) {
76	                if (isAssociatedDetached(el)) associated.add(el);
77	            }
78	            return associated;
79	        }
80	
81	        // A single document-order traversal: document order and de-duplication both come for free.
82	        for (Element el : owner.select(listedControl)) {
83	            if (isAssociated(el, owner)) associated.add(el);
84	        }
85	        return associated;
86	    }
87	
88	    /**
89	     * Ownership rules for a detached form: a {@code form} attribute cannot resolve to an owner document, so it leaves
90	     * the control unowned; otherwise ancestry applies, falling back to a parser-established link.
91	     */
92	    private boolean isAssociatedDetached(Element el) {
93	        if (formOwnerControl.matches(this, el) && el.hasAttr("form")) return false;
94	        FormElement ancestor = nearestAncestorForm(el);
95	        if (ancestor != null) return ancestor == this;
96	        return linkedEls.contains(el);
97	    }
98	
99	    /**
100	     * Apply the form ownership rules to decide whether {@code el} belongs to this form.
101	     */
102	    private boolean isAssociated(Element el, Document doc) {
103	        if (formOwnerControl.matches(doc, el) && el.hasAttr("form")) {
104	            // an explicit owner overrides ancestry outright; a dangling target means no owner at all
105	            String formId = el.attr("form");
106	            if (formId.isEmpty()) return false;
107	            return doc.getElementById(formId) == this;
108	        }
109	
110	        FormElement ancestor = nearestAncestorForm(el);
111	        if (ancestor != null) return ancestor == this;
112	
113	        // no form attribute and no ancestor: retain the parser-established association, if any
114	        return linkedEls.contains(el);
115	    }
116	
117	    /**
118	     * Find the nearest {@code FormElement} ancestor of {@code el}, if any.
119	     */
120	    private static @Nullable FormElement nearestAncestorForm(Element el) {
121	        for (Element parent = el.parent(); parent != null && !parent.nameIs("#root"); parent = parent.parent()) {
122	            if (parent instanceof FormElement) return (FormElement) parent;
123	        }
124	        return null;
125	    }
126	
127	    /**
128	     * Add a form control element to this form.
129	     * @param element form control to add
130	     * @return this form element, for chaining
131	     */
132	    public FormElement addElement(Element element) {
133	        linkedEls.add(element);
134	        return this;
135	    }
136	
137	    @Override
138	    protected void removeChild(Node out) {
139	        super.removeChild(out);
140	        linkedEls.remove(out);
141	    }
142	
143	    /**
144	     Prepare to submit this form. A Connection object is created with the request set up from the form values. This
145	     Connection will inherit the settings and the cookies (etc) of the connection/session used to request this Document
146	     (if any), as available in {@link Document#connection()}
147	     <p>You can then set up other options (like user-agent, timeout, cookies), then execute it.</p>
148	
149	     @return a connection prepared from the values of this form, in the same session as the one used to request it
150	     @throws IllegalArgumentException if the form's action URL is missing its base URI, or an absolute action URL is
151	     present but cannot be resolved. Make sure you pass the document's base URI when parsing.
152	     */
153	    public Connection submit() {
154	        String action = hasAttr("action") ? requireAbsUrl("action") : requireBaseUri();
155	        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
156	            Connection.Method.POST : Connection.Method.GET;
157	
158	        Document owner = ownerDocument();
159	        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
160	        return connection.url(action)
161	            .data(formData())
162	            .method(method);
163	    }
164	
165	    /**
166	     Prepare to submit this form, as if the given submit control was clicked. As {@link #submit()}, but the form data
167	     is collected by {@link #formData(Element, int, int)} with the given submitter and click coordinates.
168	
169	     @param submitter the submit control that triggered the submission; must be a {@code button} or an
170	     {@code input[type=submit|image]} associated with this form (present in {@link #elements()})
171	     @param x the x-coordinate of the click, used when the submitter is an {@code input[type=image]}
172	     @param y the y-coordinate of the click, used when the submitter is an {@code input[type=image]}
173	     @return a connection prepared from the values of this form, in the same session as the one used to request it
174	     @throws IllegalArgumentException if the submitter is not a usable submit control associated with this form, or if
175	     the form's action URL is missing its base URI, or an absolute action URL is present but cannot be resolved
176	     */
177	    public Connection submit(Element submitter, int x, int y) {
178	        String action = hasAttr("action") ? requireAbsUrl("action") : requireBaseUri();
179	        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
180	            Connection.Method.POST : Connection.Method.GET;
181	
182	        Document owner = ownerDocument();
183	        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
184	        return connection.url(action)
185	            .data(formData(submitter, x, y))
186	            .method(method);
187	    }
188	
189	    private String requireBaseUri() {
190	        String baseUri = baseUri();
191	        Validate.notEmpty(baseUri, "Could not determine a form action URL for submit. Ensure you set a base URI when parsing.");
192	        return baseUri;
193	    }
194	
195	    private String requireAbsUrl(String attrKey) {
196	        String action = absUrl(attrKey);
197	        Validate.notEmpty(action, String.format("Could not resolve the form's absolute %s URL for submit. Ensure you set a base URI when parsing.", attrKey));
198	        return action;
199	    }
200	
201	    /**
202	     Get the data that this form submits. The returned list is computed fresh from the form's associated controls in
203	     document order, on every call, and is independent of the DOM: modifying the list does not change the document, and
204	     controls sharing a name each contribute their own entry.
205	     <p>The controls are filtered following the HTML form submission rules:</p>
206	     <ul>
207	     <li>controls that are themselves {@code disabled}, or that are inside a {@code disabled} {@code <fieldset>}, are
208	     skipped — except for controls inside that fieldset's first {@code <legend>}; a nested disabled fieldset is not
209	     re-enabled by an outer fieldset's legend;</li>
210	     * <li>a single-selection {@code <select>} submits the first enabled selected option only; if every selected option
211	     * is disabled it submits nothing (it does not fall back to an unselected option); when nothing is selected, it
212	     * submits the first enabled option;</li>
213	     * <li>a {@code multiple} {@code <select>} submits every enabled selected option in order, and nothing if there are
214	     * none;</li>
215	     * <li>{@code <option>}s that are disabled, or that are within a disabled {@code <optgroup>}, are not eligible;</li>
216	     * <li>checkboxes and radio buttons are only included when checked;</li>
217	     * <li>{@code <input>} elements of type {@code button} and {@code image}, and {@code <button>} elements, are not
218	     * submitted; other input types (including {@code submit} and {@code reset}) are included as before.</li>
219	     * </ul>
220	     @return a fresh, independent list of key vals
221	     */
222	    public List<Connection.KeyVal> formData() {
223	        return collectFormData(null, 0, 0);
224	    }
225	
226	    /**
227	     Get the data that this form submits, as if the given submit control was clicked. Filtering and list semantics
228	     follow {@link #formData()}; the returned list is likewise computed fresh on every call and is independent of the
229	     DOM.
230	     <p>Submit controls are only counted via the {@code submitter} argument: a {@code button} or an
231	     {@code input[type=submit]} submitter contributes {@code name=value} only when it has a name; an
232	     {@code input[type=image]} submitter contributes {@code name.x=x} and {@code name.y=y} when named, or
233	     {@code x=x} and {@code y=y} when not. Other submit controls in the form (including named
234	     {@code input[type=submit]} elements, which {@link #formData()} would otherwise include) are not serialized. The
235	     submitter's entries appear at its position in document order.</p>
236	     @param submitter the submit control that triggered the submission; must be a {@code button} or an
237	     {@code input[type=submit|image]} associated with this form (present in {@link #elements()})
238	     @param x the x-coordinate of the click, used when the submitter is an {@code input[type=image]}
239	     @param y the y-coordinate of the click, used when the submitter is an {@code input[type=image]}
240	     @return a fresh, independent list of key vals
241	     @throws IllegalArgumentException if the submitter is not a usable submit control associated with this form
242	     */
243	    public List<Connection.KeyVal> formData(Element submitter, int x, int y) {
244	        requireSubmitter(submitter);
245	        return collectFormData(submitter, x, y);
246	    }
247	
248	    /**
249	     Check that {@code submitter} is a {@code button} or an {@code input[type=submit|image]} associated with this
250	     form.
251	     */
252	    private void requireSubmitter(Element submitter) {
253	        Validate.notNull(submitter, "The submitter must be a button or an input of type submit or image, associated with this form.");
254	        String type = submitter.attr("type");
255	        boolean usable = submitter.nameIs("button") ||
256	            submitter.nameIs("input") && (type.equalsIgnoreCase("submit") || type.equalsIgnoreCase("image"));
257	        Validate.isTrue(usable, "The submitter must be a button or an input of type submit or image.");
258	        Validate.isTrue(elements().contains(submitter), "The submitter must be associated with this form.");
259	    }
260	
261	    private List<Connection.KeyVal> collectFormData(@Nullable Element submitter, int x, int y) {
262	        ArrayList<Connection.KeyVal> data = new ArrayList<>();
263	
264	        // iterate the form control elements and accumulate their values
265	        for (Element el: elements()) {
266	            if (el == submitter) {
267	                // the submitter contributes at its own position in document order, per the submit control rules
268	                if (!el.hasAttr("disabled") && !inDisabledFieldset(el))
269	                    addSubmitterData(data, el, x, y);
270	                continue;
271	            }
272	            if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
273	            if (el.nameIs("button")) continue; // <button> elements are never serialized by jsoup
274	            if (el.hasAttr("disabled")) continue; // skip disabled form inputs
275	            if (inDisabledFieldset(el)) continue; // skip controls in a disabled fieldset (first legend excepted)
276	            String name = el.attr("name");
277	            if (name.length() == 0) continue;
278	            String type = el.attr("type");
279	
280	            if (type.equalsIgnoreCase("button") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these
281	            if (submitter != null && type.equalsIgnoreCase("submit")) continue; // only the submitter's submit control counts
282	
283	            if (el.nameIs("select")) {
284	                boolean multiple = el.hasAttr("multiple");
285	                Elements selected = el.select("option[selected]");
286	                if (!selected.isEmpty()) {
287	                    if (multiple) {
288	                        for (Element option : selected) {
289	                            if (isEnabledOption(option))
290	                                data.add(HttpConnection.KeyVal.create(name, option.val()));
291	                        }
292	                    } else {
293	                        // single select: only the first enabled selected option counts; if none are enabled, submit nothing
294	                        for (Element option : selected) {
295	                            if (isEnabledOption(option)) {
296	                                data.add(HttpConnection.KeyVal.create(name, option.val()));
297	                                break;
298	                            }
299	                        }
300	                    }
301	                } else if (!multiple) {
302	                    // nothing marked selected: a single select defaults to its first enabled option
303	                    for (Element option : el.select("option")) {
304	                        if (isEnabledOption(option)) {
305	                            data.add(HttpConnection.KeyVal.create(name, option.val()));
306	                            break;
307	                        }
308	                    }
309	                }
310	                // a multiple select with no enabled selected option submits nothing
311	            } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
312	                // only add checkbox or radio if they have the checked attribute
313	                if (el.hasAttr("checked")) {
314	                    final String val = el.val().length() >  0 ? el.val() : "on";
315	                    data.add(HttpConnection.KeyVal.create(name, val));
316	                }
317	            } else {
318	                data.add(HttpConnection.KeyVal.create(name, el.val()));
319	            }
320	        }
321	        return data;
322	    }
323	
324	    /**
325	     Add the submitter's own contribution to the form data: a named {@code button} or {@code input[type=submit]}
326	     contributes {@code name=value}; an {@code input[type=image]} contributes {@code name.x} / {@code name.y} with the
327	     click coordinates, or {@code x} / {@code y} when it has no name.
328	     */
329	    private static void addSubmitterData(ArrayList<Connection.KeyVal> data, Element submitter, int x, int y) {
330	        String name = submitter.attr("name");
331	        if (submitter.nameIs("input") && submitter.attr("type").equalsIgnoreCase("image")) {
332	            String prefix = name.isEmpty() ? "" : name + ".";
333	            data.add(HttpConnection.KeyVal.create(prefix + "x", String.valueOf(x)));
334	            data.add(HttpConnection.KeyVal.create(prefix + "y", String.valueOf(y)));
335	        } else if (!name.isEmpty()) { // a button or submit input only contributes when named
336	            data.add(HttpConnection.KeyVal.create(name, submitter.val()));
337	        }
338	    }
339	
340	    /**
341	     Check if a control is excluded by a disabled ancestor fieldset. A disabled fieldset disables its descendants,
342	     except for those inside its first {@code legend} child's subtree. A nested disabled fieldset stays disabled even
343	     when it sits within an outer fieldset's exempt legend.
344	     @param el the control to check
345	     @return true if the control is within a disabled fieldset without an exempting legend
346	     */
347	    private static boolean inDisabledFieldset(Element el) {
348	        Element child = el;
349	        for (Element parent = el.parent(); parent != null && !parent.nameIs("#root"); child = parent, parent = parent.parent()) {
350	            if (parent.nameIs("fieldset") && parent.hasAttr("disabled") && !isFirstLegendChild(child, parent))
351	                return true;
352	            // if exempted by this fieldset's first legend, keep climbing — an outer disabled fieldset may still apply
353	        }
354	        return false;
355	    }
356	
357	    /**
358	     Check if {@code child} is the first {@code legend} child of {@code fieldset}; the subtree of that legend is
359	     exempted from the fieldset's disabled state.
360	     */
361	    private static boolean isFirstLegendChild(Element child, Element fieldset) {
362	        if (!child.nameIs("legend")) return false;
363	        for (Element fieldsetChild : fieldset.children()) {
364	            if (fieldsetChild.nameIs("legend")) return fieldsetChild == child; // first legend encountered in tree order
365	        }
366	        return false;
367	    }
368	
369	    /**
370	     Check if an option is eligible for submission: not itself disabled, and not inside a disabled optgroup.
371	     @param option the option to check
372	     @return true if the option may be submitted
373	     */
374	    private static boolean isEnabledOption(Element option) {
375	        if (!option.nameIs("option") || option.hasAttr("disabled")) return false;
376	        Element parent = option.parent();
377	        if (parent != null && parent.nameIs("optgroup") && parent.hasAttr("disabled")) return false;
378	        return true;
379	    }
380	
381	    @Override
382	    public FormElement clone() {
383	        return (FormElement) super.clone();
384	    }
385	}
